import timeimport cv2import csvfrom datetime import datetimedef speed_tracking(v_km_s,track_id,cen_car,start_line, left_side_car,a_start_line,dict_cars_speed,counter_car,cadr_time,s,frame,x,y,dict_cars_direction):    # Если находится слева от линии и потом пересекает линию, то добавляем в счетчик    if cen_car[0]<start_line[0]:        left_side_car.add(track_id)    if cen_car[0]>=a_start_line[0]:        start_time =time.time()        if len(dict_cars_speed[track_id]) == 0:            dict_cars_speed[track_id].append(start_time)    if cen_car[0] >= start_line[0] and track_id in left_side_car:        counter_car.add(track_id)        end_time = time.time()        if len(dict_cars_speed[track_id]) == 1:            dict_cars_speed[track_id].append(end_time)            t_A = dict_cars_speed[track_id][0]            t_B = dict_cars_speed[track_id][-1]            delta_time = t_B - t_A            v_m_s = s/delta_time            v_km_s = cadr_time*v_m_s            direction_str = dict_cars_direction[track_id][-1] if dict_cars_direction.get(track_id) else 'N/A'            crossing_time = datetime.now().strftime('%Y-%m-%d %H:%M:%S.%f')[:-3]            with open('final/vehicle_tracking_log.csv', mode='a', newline='') as file:                writer = csv.writer(file)                # Округляем значения для красоты записи                writer.writerow([                    track_id,                    direction_str,                    crossing_time,                    round(t_A, 3),                    round(t_B, 3),                    round(delta_time, 3),                    s,                    round(v_km_s, 2)                ])        if v_km_s > 0:            cv2.putText(frame, str(v_km_s), (x, y+100),cv2.FONT_HERSHEY_SIMPLEX,2, (255, 0, 0), 2)